var currentLanguage = "zh";
/** Set the active language. Call this when app_config.language changes. */
function setLanguage(language) {
	currentLanguage = language;
}
function getLanguage() {
	return currentLanguage;
}
/**
* Look up a translation key and optionally interpolate `{param}` placeholders.
* Returns the key itself if no translation exists.
*
*   t('imMissingCredentials', { fields: 'appId, appSecret' })
*   // => "缺少必要配置项: appId, appSecret"
*/
function t(key, params) {
	let text = translations[currentLanguage][key] ?? translations[currentLanguage === "zh" ? "en" : "zh"][key] ?? key;
	if (params) for (const [k, v] of Object.entries(params)) text = text.replace(`{${k}}`, String(v));
	const productName = currentLanguage === "zh" ? BRAND.nameZh : BRAND.nameEn;
	return text.replaceAll("网易有道LobsterAI", productName).replaceAll("NetEase Youdao LobsterAI", productName).replaceAll("LobsterAI", productName);
}
