	getConfigValue(key) {
		const row = this.db.prepare("SELECT value FROM im_config WHERE key = ?").get(key);
		if (!row) return void 0;
		const value = row.value;
		try {
			return JSON.parse(value);
		} catch (error) {
			console.warn(`Failed to parse im_config value for ${key}`, error);
			return;
		}
	}
	setConfigValue(key, value) {
		const now = Date.now();
		this.db.prepare(`
      INSERT INTO im_config (key, value, updated_at)
      VALUES (?, ?, ?)
      ON CONFLICT(key) DO UPDATE SET
        value = excluded.value,
        updated_at = excluded.updated_at
    `).run(key, JSON.stringify(value), now);
	}
	getConfig() {
		const dingtalkMulti = this.getDingTalkMultiInstanceConfig();
		const telegramMulti = this.getTelegramMultiInstanceConfig();
		const discordMulti = this.getDiscordMultiInstanceConfig();
		const nimMulti = this.getNimMultiInstanceConfig();
		const neteaseBeeChan = this.getConfigValue("netease-bee") ?? DEFAULT_NETEASE_BEE_CONFIG;
		const qqMulti = this.getQQMultiInstanceConfig();
		const feishuMulti = this.getFeishuMultiInstanceConfig();
		const wecomMulti = this.getWecomMultiInstanceConfig();
		const popoMulti = this.getPopoMultiInstanceConfig();
		const weixin = this.getConfigValue("weixin") ?? DEFAULT_WEIXIN_CONFIG;
		const settings = this.getConfigValue("settings") ?? DEFAULT_IM_SETTINGS;
		const email = this.getEmailConfig();
		const resolveEnabled = (stored, defaults) => {
			const merged = {
				...defaults,
				...stored
			};
			if (stored.enabled === void 0) return {
				...merged,
				enabled: false
			};
			return merged;
		};
		return {
			dingtalk: dingtalkMulti,
			feishu: feishuMulti,
			telegram: telegramMulti,
			discord: discordMulti,
			nim: nimMulti,
			"netease-bee": resolveEnabled(neteaseBeeChan, DEFAULT_NETEASE_BEE_CONFIG),
			qq: qqMulti,
			wecom: wecomMulti,
			popo: popoMulti,
			weixin: resolveEnabled(weixin, DEFAULT_WEIXIN_CONFIG),
			email,
			settings: {
				...DEFAULT_IM_SETTINGS,
				...settings
			}
		};
	}
	setConfig(config) {
		if (config.dingtalk) this.setDingTalkMultiInstanceConfig(config.dingtalk);
		if (config.feishu) this.setFeishuMultiInstanceConfig(config.feishu);
		if (config.telegram) this.setTelegramMultiInstanceConfig(config.telegram);
		if (config.discord) this.setDiscordMultiInstanceConfig(config.discord);
		if (config.nim) this.setNimMultiInstanceConfig(config.nim);
		if (config["netease-bee"]) this.setNeteaseBeeChanConfig(config["netease-bee"]);
		if (config.qq) this.setQQMultiInstanceConfig(config.qq);
		if (config.wecom) this.setWecomMultiInstanceConfig(config.wecom);
		if (config.popo) this.setPopoMultiInstanceConfig(config.popo);
		if (config.weixin) this.setWeixinConfig(config.weixin);
		if (config.email) this.setEmailConfig(config.email);
		if (config.settings) this.setIMSettings(config.settings);
	}
	/** @deprecated Use getDingTalkMultiInstanceConfig() or getDingTalkInstances() instead */
	getDingTalkOpenClawConfig() {
		const stored = this.getConfigValue("dingtalkOpenClaw");
		return {
			...DEFAULT_DINGTALK_OPENCLAW_CONFIG,
			...stored
		};
	}
