	/**
	* Start all enabled gateways.
	*
	* Active OpenClaw platforms are batched
	* so that `syncOpenClawConfig` + `ensureOpenClawGatewayConnected` are called
	* only **once** regardless of how many OpenClaw platforms are enabled.
	* This avoids N serial gateway restarts which cause message loss, Telegram
	* `getUpdates` conflicts, and rate-limit issues.
	*/
	async startAllEnabled() {
		const config = this.getConfig();
		this.updateChatHandler();
		const openClawPlatformsToStart = [];
		if ((config.dingtalk?.instances || []).some((i) => i.enabled && i.clientId && i.clientSecret)) openClawPlatformsToStart.push("dingtalk");
		if ((config.feishu?.instances || []).some((i) => i.enabled && i.appId && i.appSecret)) openClawPlatformsToStart.push("feishu");
		if ((config.qq?.instances || []).some((i) => i.enabled && i.appId && i.appSecret)) openClawPlatformsToStart.push("qq");
		if ((config.wecom?.instances || []).some((i) => i.enabled && i.botId && i.secret)) openClawPlatformsToStart.push("wecom");
		if (config.weixin?.enabled) openClawPlatformsToStart.push("weixin");
		if (openClawPlatformsToStart.length > 0) {
			console.log(`[IMGatewayManager] Starting OpenClaw platforms in batch: ${openClawPlatformsToStart.join(", ")}`);
			try {
				await this.syncOpenClawConfig?.(`im-gateway-start-batch:${openClawPlatformsToStart.join(",")}`);
				await this.ensureOpenClawGatewayConnected?.();
			} catch (error) {
				console.error(`[IMGatewayManager] Failed to start OpenClaw platforms: ${error.message}`);
			}
		}
	}
	async stopAll() {}
	isAnyConnected() {
		return false;
	}
	isConnected(platform) {
		if (platform === "dingtalk") return (this.getConfig().dingtalk?.instances || []).some((i) => i.enabled && i.clientId && i.clientSecret);
		if (platform === "feishu") return (this.getConfig().feishu?.instances || []).some((i) => i.enabled && i.appId && i.appSecret);
		if (platform === "telegram") return (this.getConfig().telegram?.instances || []).some((i) => i.enabled && i.botToken);
		if (platform === "discord") return (this.getConfig().discord?.instances || []).some((i) => i.enabled && i.botToken);
		if (platform === "nim") return (this.getConfig().nim?.instances || []).some((i) => i.enabled && (i.nimToken && i.nimToken.trim() || i.appKey && i.account && i.token));
		if (platform === "netease-bee") {
			const config = this.getConfig();
			return Boolean(config["netease-bee"]?.enabled && config["netease-bee"]?.clientId && config["netease-bee"]?.secret);
		}
		if (platform === "qq") return (this.getConfig().qq?.instances || []).some((i) => i.enabled && i.appId && i.appSecret);
		if (platform === "wecom") return (this.getConfig().wecom?.instances || []).some((i) => i.enabled && i.botId && i.secret);
		if (platform === "weixin") {
			const config = this.getConfig();
			return Boolean(config.weixin?.enabled);
		}
		if (platform === "popo") return (this.getConfig().popo?.instances || []).some((i) => i.enabled && i.appKey && i.appSecret && i.aesKey && (i.connectionMode === "websocket" || i.token));
		return false;
	}
	async sendNotification(platform, _text) {
		if (!this.isConnected(platform)) {
			console.warn(`[IMGatewayManager] Cannot send notification: ${platform} is not connected`);
			return false;
		}
		try {
			if (platform === "nim") console.log("[IMGatewayManager] NIM notification via OpenClaw not yet supported");
			else if (platform === "qq") console.log("[IMGatewayManager] QQ notification via OpenClaw not yet supported");
			else if (platform === "wecom") console.log("[IMGatewayManager] WeCom notification via OpenClaw not yet supported");
			else if (platform === "weixin") console.debug("[IMGatewayManager] Weixin notification via OpenClaw not yet supported");
			else if (platform === "popo") console.log("[IMGatewayManager] POPO notification via OpenClaw not yet supported");
			else if (platform === "netease-bee") console.log("[IMGatewayManager] netease-bee notification via OpenClaw not yet supported");
			return true;
		} catch (error) {
			console.error(`[IMGatewayManager] Failed to send notification via ${platform}:`, error.message);
			return false;
		}
	}
