	async testTelegramOpenClawConnectivity(configOverride) {
		const checks = [];
		const testedAt = Date.now();
		const platform = "telegram";
		const instances = this.buildMergedConfig(configOverride).telegram?.instances || [];
		const botToken = (instances.find((i) => i.enabled && i.botToken) || instances[0])?.botToken || "";
		if (!botToken) {
			checks.push({
				code: "missing_credentials",
				level: "fail",
				message: t("imTelegramMissingBotToken"),
				suggestion: t("imTelegramFillBotToken")
			});
			return {
				platform,
				testedAt,
				verdict: "fail",
				checks
			};
		}
		try {
			const response = await this.withTimeout(fetchJsonWithTimeout(`https://api.telegram.org/bot${botToken}/getMe`, {}, CONNECTIVITY_TIMEOUT_MS), CONNECTIVITY_TIMEOUT_MS, t("imAuthProbeTimeout"));
			if (response?.ok && response.result?.username) checks.push({
				code: "auth_check",
				level: "pass",
				message: t("imTelegramAuthPassed", { username: response.result.username })
			});
			else {
				checks.push({
					code: "auth_check",
					level: "fail",
					message: t("imTelegramAuthFailed", { error: response?.description || t("imTelegramAuthFailedUnknown") }),
					suggestion: t("imTelegramCheckToken")
				});
				return {
					platform,
					testedAt,
					verdict: "fail",
					checks
				};
			}
		} catch (error) {
			checks.push({
				code: "auth_check",
				level: "fail",
				message: t("imTelegramAuthFailed", { error: error.message }),
				suggestion: t("imTelegramCheckTokenNetwork")
			});
			return {
				platform,
				testedAt,
				verdict: "fail",
				checks
			};
		}
		checks.push({
			code: "gateway_running",
			level: "info",
			message: t("imTelegramOpenClawHint")
		});
		return {
			platform,
			testedAt,
			verdict: checks.some((c) => c.level === "fail") ? "fail" : checks.some((c) => c.level === "warn") ? "warn" : "pass",
			checks
		};
	}
