		const activeTurnSessionKey = this.activeTurns.get(sessionId)?.sessionKey?.trim();
		const rememberedSessionKey = this.getSessionKeysForSession(sessionId).find((key) => !isManagedSessionKey(key));
		const persistedChannelSession = this.channelSessionSync?.getOpenClawSessionKeyForCoworkSession(sessionId);
		const persistedChannelSessionKey = persistedChannelSession?.sessionKey && !isManagedSessionKey(persistedChannelSession.sessionKey) ? persistedChannelSession.sessionKey : "";
