	ipcMain.handle(MeetingRoomIpcChannel.Resume, (_event, input) => coordinator.resume(readMeetingIdInput(input)));
	ipcMain.handle(MeetingRoomIpcChannel.Stop, (_event, input) => coordinator.stop(readMeetingIdInput(input)));
	ipcMain.handle(MeetingRoomIpcChannel.AppendRound, (_event, input) => {
		if (!input || typeof input !== "object") throw new Error("MEETING_INVALID_INPUT");
		const value = input;
		return coordinator.appendRound(validateMeetingId(value.meetingId), value.supplement);
	});
