	/**
	* Start Web Search Bridge Server
	*/
	async startWebSearchService() {
		try {
			const skillPath = this.getWebSearchPath();
			if (!skillPath) {
				console.log("[SkillServices] Web Search skill not found, skipping");
				return;
			}
			if (this.isWebSearchServiceRunning()) {
				console.log("[SkillServices] Web Search service already running");
				return;
			}
			console.log("[SkillServices] Starting Web Search Bridge Server...");
			await this.startWebSearchServiceProcess(skillPath);
			const pidFile = path.default.join(skillPath, ".server.pid");
			const deadline = Date.now() + 1e4;
			while (Date.now() < deadline) {
				if (fs.default.existsSync(pidFile)) break;
				await new Promise((r) => setTimeout(r, 200));
			}
			if (fs.default.existsSync(pidFile)) {
				const pid = parseInt(fs.default.readFileSync(pidFile, "utf-8").trim());
				this.webSearchPid = pid;
				console.log(`[SkillServices] Web Search Bridge Server started (PID: ${pid})`);
			} else console.warn("[SkillServices] Web Search Bridge Server may not have started correctly");
		} catch (error) {
			console.error("[SkillServices] Failed to start Web Search service:", error);
		}
	}
	async startWebSearchServiceProcess(skillPath) {
		const pidFile = path.default.join(skillPath, ".server.pid");
		const logFile = path.default.join(skillPath, ".server.log");
		const serverEntry = path.default.join(skillPath, "dist", "server", "index.js");
		this.ensureWebSearchRuntimeReady(skillPath);
		const baseEnv = this.skillEnv ?? process.env;
		const runtime = this.resolveNodeRuntime(baseEnv);
		const electronNodeRuntimePath = getElectronNodeRuntimePath();
		const env = {
			...baseEnv,
			...runtime.extraEnv ?? {},
			LOBSTERAI_ELECTRON_PATH: electronNodeRuntimePath
		};
		const logFd = fs.default.openSync(logFile, "a");
		let child;
		try {
			child = (0, child_process.spawn)(runtime.command, [...runtime.args, serverEntry], {
				cwd: skillPath,
				detached: true,
				stdio: [
					"ignore",
					logFd,
					logFd
				],
				env,
				windowsHide: process.platform === "win32"
			});
		} finally {
			fs.default.closeSync(logFd);
		}
		fs.default.writeFileSync(pidFile, child.pid.toString());
		child.unref();
		const runtimeLabel = runtime.command === "node" ? "node" : "electron-node";
		console.log(`[SkillServices] Web Search Bridge Server starting (PID: ${child.pid}, runtime: ${runtimeLabel})`);
		console.log(`[SkillServices] Logs: ${logFile}`);
	}
	/**
	* Stop Web Search Bridge Server
	*/
	async stopWebSearchService() {
		try {
			const skillPath = this.getWebSearchPath();
			if (!skillPath) return;
			if (!this.isWebSearchServiceRunning()) {
				console.log("[SkillServices] Web Search service not running");
				return;
			}
			console.log("[SkillServices] Stopping Web Search Bridge Server...");
			if (this.webSearchPid) try {
				process.kill(this.webSearchPid, "SIGTERM");
			} catch (error) {
				console.warn("[SkillServices] Failed to kill process:", error);
			}
			const pidFile = path.default.join(skillPath, ".server.pid");
			if (fs.default.existsSync(pidFile)) fs.default.unlinkSync(pidFile);
			await new Promise((resolve) => setTimeout(resolve, 2e3));
			console.log("[SkillServices] Web Search Bridge Server stopped");
			this.webSearchPid = null;
		} catch (error) {
			console.error("[SkillServices] Failed to stop Web Search service:", error);
		}
	}
	/**
	* Check if Web Search service is running
	*/
	isWebSearchServiceRunning() {
		if (this.webSearchPid === null) {
			const skillPath = this.getWebSearchPath();
			if (!skillPath) return false;
			const pidFile = path.default.join(skillPath, ".server.pid");
			if (fs.default.existsSync(pidFile)) try {
				const pid = parseInt(fs.default.readFileSync(pidFile, "utf-8").trim());
				this.webSearchPid = pid;
			} catch {
				return false;
			}
			else return false;
		}
		try {
			process.kill(this.webSearchPid, 0);
			return true;
		} catch {
			this.webSearchPid = null;
			return false;
		}
	}
	/**
	* Get Web Search skill path
	*/
	getWebSearchPath() {
		const candidates = [];
		if (electron.app.isPackaged) {
			candidates.push(path.default.join(electron.app.getPath("userData"), "SKILLs", "web-search"));
			candidates.push(path.default.join(process.resourcesPath, "SKILLs", "web-search"));
			candidates.push(path.default.join(electron.app.getAppPath(), "SKILLs", "web-search"));
		} else {
			const projectRoot = path.default.resolve(__dirname, "..");
			candidates.push(path.default.join(projectRoot, "SKILLs", "web-search"));
			candidates.push(path.default.join(electron.app.getAppPath(), "SKILLs", "web-search"));
		}
		return candidates.find((skillPath) => fs.default.existsSync(skillPath)) ?? null;
	}
	/**
	* Get service status
	*/
	getStatus() {
		return { webSearch: this.isWebSearchServiceRunning() };
	}
	/**
	* Health check for Web Search service
	*/
	async checkWebSearchHealth() {
		try {
			return (await fetch("http://127.0.0.1:8923/api/health", {
				method: "GET",
				signal: AbortSignal.timeout(3e3)
			})).ok;
		} catch {
			return false;
		}
	}
